SELECT ?s ?ts WHERE {
  ?z a brick:Zone ; brick:hasSubType ?st ; ?p ?x .
  FILTER (str(?z) LIKE "%Perimeter_ZN_1")
}

SELECT ?sensor ?point ?ts WHERE {
  ?sensor a brick:ElectricPowerSensor ; brick:hasPropertyParameter ?type ; ref:hasExternalReference ?point .
  ?point ref:timeseriesId ?ts .
  ?sensor brick:isPointOf ?zone .
  FILTER (str(?zone) LIKE "%Perimeter_ZN_1%")
}

SELECT ?label WHERE {
  ?s a brick:ElectricPowerSensor .
  OPTIONAL { ?s rdfs:label ?label }
  OPTIONAL { ?s brick:hasSubType ?st }
}

SELECT ?s ?cls WHERE {
  ?s a brick:Zone .
  FILTER regex(str(?s), "Perimeter_ZN_1")
}

